const b = $json.body;
if (b?.error) throw new Error(`list_posts: ${b.error.message}`);
return JSON.parse(b.result.content[0].text).posts.map((p) => ({ json: p }));

// The weekly state of the corpus, from the repository rather than from memory.
const RETEST_DAYS = 120;
const posts = $input.all().map((i) => JSON.parse(i.json.body.result.content[0].text));
const live = posts.filter((p) => !p.frontmatter.draft);

const slugs = new Set(live.map((p) => p.slug));
const inbound = new Map(live.map((p) => [p.slug, 0]));
const thin = [];
const noHero = [];
const noFaq = [];
const stale = [];
const byPillar = {};
let tested = 0;

for (const p of live) {
  const f = p.frontmatter;
  byPillar[f.pillar] = (byPillar[f.pillar] ?? 0) + 1;
  if (f.testedOn?.date) {
    tested += 1;
    const due = new Date(f.testedOn.date).getTime() + RETEST_DAYS * 86400000;
    if (due < Date.now()) stale.push(`${p.slug} (due ${new Date(due).toISOString().slice(0, 10)})`);
  }
  if (!f.heroImage) noHero.push(p.slug);
  if (!f.faq || f.faq.length === 0) noFaq.push(p.slug);

  const links = [...String(p.body).matchAll(/\]\((\/[^)\s#]+)/g)]
    .map((m) => m[1].replace(/^\/|\/$/g, ''))
    .filter((s) => slugs.has(s) && s !== p.slug);
  if (new Set(links).size < 2) thin.push(`${p.slug} (${new Set(links).size})`);
  for (const l of new Set(links)) inbound.set(l, (inbound.get(l) ?? 0) + 1);
}

const orphans = [...inbound].filter(([, n]) => n === 0).map(([s]) => s);
const pillars = Object.entries(byPillar).sort((a, b) => b[1] - a[1]);
const empty = ['windows-mac','phones','excel-office','ai-tools','websites-hosting','automation']
  .filter((p) => !byPillar[p]);

const block = (title, items) =>
  items.length ? `${title} (${items.length})\n  ${items.join('\n  ')}\n` : `${title}: none\n`;

const report = [
  `Live posts: ${live.length}    Tested: ${tested}    With a hero: ${live.length - noHero.length}`,
  '',
  'Posts per pillar',
  ...pillars.map(([k, v]) => `  ${k.padEnd(20)} ${v}`),
  empty.length ? `  EMPTY: ${empty.join(', ')}` : '',
  '',
  block('Fewer than two internal links', thin),
  block('No inbound link from any post', orphans),
  block('No hero image', noHero),
  block('No FAQ', noFaq),
  block('Due for re-test', stale),
].filter((l) => l !== '').join('\n');

return [{ json: { report, live: live.length, actions: thin.length + orphans.length + stale.length } }];
